import{l as o,b as t,c as s,g as r}from"./chunks/framework.Du5_AGGE.js";const u=JSON.parse('{"title":"中国古代纪时考","description":"","frontmatter":{"title":"中国古代纪时考","subTitle":"纪时刻与时辰","author":"oasis","date":"2026-10-27T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/zhong-guo-gudai-ji-shi-kao/2.md","filePath":"articles/books/zhong-guo-gudai-ji-shi-kao/2.md"}'),l={name:"articles/books/zhong-guo-gudai-ji-shi-kao/2.md"};function n(g,i,a,e,p,h){return t(),s("div",null,[...i[0]||(i[0]=[r('<h2 id="时的定义" tabindex="-1">时的定义</h2><p>把一昼夜划分为若干时段，由此形成的时间单位。</p><h2 id="时制的发展阶段" tabindex="-1">时制的发展阶段</h2><p>时制分两段：先把昼夜分成若干不等长的时段，再分成等长的时段。</p><h3 id="不等时" tabindex="-1">不等时</h3><p>昼的分段，主要看太阳出没，也参照长期形成的生活规律。</p><p>从日出到日落，甲骨文分为八个时段：旦、朝（大采）、大食、中日、昃、小食（郭兮）、暮（小采）、各（落）日。</p><p>夜的分段，主要看星象，也参照物候。甲骨文里与夜相关的名称有妹旦、昏、夕。妹旦指太阳刚落山；昏指太阳落山后，天色转暗，仍有余光。</p><h3 id="等时" tabindex="-1">等时</h3><p>中国古代长期用漏刻计时，把一昼夜等分为一百刻，即百刻制。《说文》：“漏，以铜受水，刻节，昼夜百节。”百节就是百刻。一日百刻分为昼、夜两部分，叫昼漏、夜漏。</p><ul><li><strong>二分</strong>（春分、秋分）：昼夜等长，昼漏、夜漏各五十刻。</li><li><strong>二至</strong>：夏至昼最长、夜最短，冬至相反。夏至昼漏六十刻、夜漏四十刻；冬至昼漏四十刻、夜漏六十刻。</li></ul><p>《尚书·尧典》孔颖达《尚书正义》引马融：“古制刻漏，昼夜百刻。昼长六十刻，夜短四十刻。昼短四十刻，夜长六十刻。昼中五十刻，夜亦五十刻。”</p><p>百刻的刻数后来改过，有过一百零八刻，也有过九十六刻。明末清初，日耳曼人汤若望进呈《西洋新法历书》，把昼夜定为九十六刻，沿用到清亡。</p><h2 id="时辰纪时" tabindex="-1">时辰纪时</h2><p>最早是一日四时辰。《左传·昭公元年》：“君子有四时：朝以听政，昼以访问，夕以修令，夜以安身。”</p><p>先秦曾经用一日十时。秦汉把一昼夜分为十六个时辰，行用一日十六时制。</p><p>十二时的名称，考古材料早于传世文献。1975 年湖北云梦睡虎地十一号秦墓出土的乙种《日书》，已把十二时辰与十二支相配。传世文献里较早写明一日分十二时的，是东汉初年王充《论衡·谰时》：“一日之中分为十二时：平旦，寅；日出，卯也。”秦汉时期，一日十六时与一日十二时并行。</p><p>睡虎地《日书》的配法：</p><ul><li><strong>丑</strong>：鸡鸣</li><li><strong>寅</strong>：平旦</li><li><strong>卯</strong>：日出</li><li><strong>辰</strong>：食时</li><li><strong>巳</strong>：莫食</li><li><strong>午</strong>：日中</li><li><strong>未</strong>：日失</li><li><strong>申</strong>：下市</li><li><strong>酉</strong>：舂日</li><li><strong>戌</strong>：牛羊入</li><li><strong>亥</strong>：黄昏</li><li><strong>子</strong>：人定</li></ul><p>后来通行的十二时，名称和地支的搭配与秦简不完全相同：</p><ul><li><strong>子</strong>：夜半</li><li><strong>丑</strong>：鸡鸣</li><li><strong>寅</strong>：平旦</li><li><strong>卯</strong>：日出</li><li><strong>辰</strong>：食时</li><li><strong>巳</strong>：隅中</li><li><strong>午</strong>：日中</li><li><strong>未</strong>：日昳（dié）</li><li><strong>申</strong>：晡（bū）时</li><li><strong>酉</strong>：日入</li><li><strong>戌</strong>：黄昏</li><li><strong>亥</strong>：人定</li></ul><p>同书：<a href="/articles/books/zhong-guo-gudai-ji-shi-kao/1.html">纪日</a>、<a href="/articles/books/zhong-guo-gudai-ji-shi-kao/3.html">纪月</a>、<a href="/articles/books/zhong-guo-gudai-ji-shi-kao/4.html">纪年</a>。</p>',22)])])}const _=o(l,[["render",n]]);export{u as __pageData,_ as default};
